{"path": "scale_generator.py", "content": "class Scale:
    SHARPS = ["A", "A#", "B", "C", "C#", "D", "D#", "E", "F", "F#", "G", "G#"]
    FLATS = ["A", "Bb", "B", "C", "Db", "D", "Eb", "E", "F", "Gb", "G", "Ab"]
    FLAT_TONICS = {"F", "Bb", "Eb", "Ab", "Db", "Gb",
                   "d", "g", "c", "f", "bb", "eb"}
    STEPS = {"m": 1, "M": 2, "A": 3}

    def __init__(self, tonic):
        self.tonic = tonic[0].upper() + tonic[1:]
        names = self.FLATS if tonic in self.FLAT_TONICS else self.SHARPS
        self.names = names
        self.start = names.index(self.tonic)

    def chromatic(self):
        return [self.names[(self.start + i) % 12] for i in range(12)]

    def interval(self, intervals):
        idx = self.start
        result = [self.names[idx]]
        for step in intervals:
            idx = (idx + self.STEPS[step]) % 12
            result.append(self.names[idx])
        return result
